}
export function guardUnfinishedGroups(directory: string, workspace: string, filePath: string, exceptId?: string) {
    if (!fs.existsSync(directory))
        return;
    const target = path.resolve(workspace, filePath).toLowerCase();
    for (const name of fs.readdirSync(directory)) {
        if (!name.endsWith('.json') || !validGroupId(name.slice(0, -5)))
            continue;
        const journal = readGroupJournal(directory, name.slice(0, -5));
        if (!journal || journal.id === exceptId || journal.phase === 'saved' || journal.phase === 'undone')
            continue;
        if (journal.members.some(m => path.resolve(workspace, m.filePath).toLowerCase() === target))
            throw new Error('An interrupted change set owns this file. Check and explicitly resume that change set first.');
    }
}

import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { performance } from 'node:perf_hooks';

const heldKey = Symbol.for('slightnudge.sourceOperationLocks');
const globalLocks = globalThis as typeof globalThis & { [heldKey]?: Set<string> };
// Native process start identity is shared by worker threads and survives module
// reloads. A VM-local UUID cannot distinguish a live worker from a reused PID.
const processStart = performance.timeOrigin;

export class SourceOperationBusyError extends Error {
  readonly code = 'SOURCE_OPERATION_BUSY';
  constructor() { super('Another source operation is in progress. Wait for it to finish, then try again.'); }
}

function alive(pid: number) {
  try { process.kill(pid, 0); return true; }
  catch (error) { return (error as NodeJS.ErrnoException).code !== 'ESRCH'; }
}

/**
