  const held = globalLocks[heldKey] ||= new Set<string>();
  if (held.has(root)) return operation(); // Nested synchronous history helpers.
  const name = `${process.pid}-${randomUUID()}.json`;
  const own = path.join(root, name);
  const readOthers = () => {
    const entries: Array<{ name: string; ticket: number | null }> = [];
    for (const entry of fs.readdirSync(root)) {
      const match = /^(\d+)-[0-9a-f-]{36}\.json$/i.exec(entry);
      if (!match || entry === name) continue;
      const pid = Number(match[1]);
      if (!Number.isSafeInteger(pid) || pid < 1) throw new SourceOperationBusyError();
      if (!alive(pid)) {
        // Unique filenames cannot refer to a replacement owner. No lease expiry
        // is used, so a slow/live process is never mistaken for a dead owner.
        try { fs.unlinkSync(path.join(root, entry)); } catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
        continue;
      }
      let contents: string;
      try { contents = fs.readFileSync(path.join(root, entry), 'utf8'); }
      catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue; throw error; }
      try {
        const data = JSON.parse(contents);
        if (data.pid !== pid || (data.ticket !== null && (!Number.isSafeInteger(data.ticket) || data.ticket < 1))) throw new Error('Invalid ticket');
        if (pid === process.pid && typeof data.processStart === 'number' && data.processStart !== processStart) {
          // A restarted process can reuse its predecessor's PID. In the same
          // PID namespace that predecessor cannot still be alive. Module reloads
          // share the same native process origin, so live workers are not stolen.
          try { fs.unlinkSync(path.join(root, entry)); } catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
          continue;
        }
        entries.push({ name: entry, ticket: data.ticket });
      } catch { throw new SourceOperationBusyError(); }
    }
    return entries;
  };
  // Publish choosing before observing other tickets; partial choosing writes
  // fail closed in other processes. Updates below use atomic replacement.
  const fd = fs.openSync(own, 'wx');
  try {
    try { fs.writeFileSync(fd, JSON.stringify({ pid: process.pid, processStart, ticket: null })); fs.fsyncSync(fd); }
    finally { fs.closeSync(fd); }
    const ticket = Math.max(0, ...readOthers().map(entry => entry.ticket || 0)) + 1;
    if (!Number.isSafeInteger(ticket)) throw new SourceOperationBusyError();
    const temporary = `${own}.tmp`;
    const update = fs.openSync(temporary, 'wx');
    try { fs.writeFileSync(update, JSON.stringify({ pid: process.pid, processStart, ticket })); fs.fsyncSync(update); }
    finally { fs.closeSync(update); }
    // Windows can briefly deny replacement while another contender reads our
    // choosing ticket. Keep that ticket published while retrying; never enter
    // the critical section until the final ticket has been replaced atomically.
    for (let attempt = 0; ; attempt++) {
      try { fs.renameSync(temporary, own); break; }
      catch (error) {
        if (!['EPERM', 'EBUSY', 'EACCES'].includes((error as NodeJS.ErrnoException).code || '')) throw error;
        if (attempt >= 3) throw new SourceOperationBusyError();
        Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10 * 2 ** attempt);
      }
    }
    for (const other of readOthers()) {
      if (other.ticket === null || other.ticket < ticket || (other.ticket === ticket && other.name < name)) throw new SourceOperationBusyError();
    }
    held.add(root);
    try { return operation(); }
    finally { held.delete(root); }
  } finally {
    // Cleanup failure cannot turn an accepted source/history mutation into a
    // reported failed write. An undeleted live ticket blocks further mutations.
    try { fs.unlinkSync(own); } catch { /* A dead owner's unique ticket can be cleared on restart. */ }
    try { fs.unlinkSync(`${own}.tmp`); } catch { /* Not an active ticket. */ }
  }
}

/** Tab-local references for a write whose response or UI confirmation may be lost.
 * This cache is never evidence that source was saved; only server status is. */
export interface StudioRecoveryRecord {
  version: 1;
  operationId: string;
  kind: 'apply' | 'undo';
  previewId: string;
  editId?: string;
  repositoryId?: string;
  sourcePath?: string;
  filePath: string;
  startedAt: number;
  view: unknown;
}

export interface RecoveryStorage { getItem(key: string): string | null; setItem(key: string, value: string): void; removeItem(key: string): void }
const maxBytes = 256 * 1024;
const keyFor = (repositoryId?: string) => `slightnudge:write-recovery:v1:${repositoryId === undefined ? 'workspace' : `project:${encodeURIComponent(repositoryId)}`}`;
const shortString = (value: unknown, max = 1000): value is string => typeof value === 'string' && value.length > 0 && value.length <= max;
const browserStorage = () => window.sessionStorage;

export type RecoveryRead = { status: 'empty' } | { status: 'found'; record: StudioRecoveryRecord } | { status: 'unavailable'; error: string };

export function readStudioRecovery(repositoryId?: string, storage?: RecoveryStorage): RecoveryRead {
  try {
    const raw = (storage || browserStorage()).getItem(keyFor(repositoryId));
    if (!raw) return { status: 'empty' };
    if (raw.length > maxBytes) throw new Error('Oversized recovery record');
    const record = JSON.parse(raw) as StudioRecoveryRecord;
    if (record.version !== 1 || !shortString(record.operationId, 128) || !['apply', 'undo'].includes(record.kind) ||
      !shortString(record.previewId, 128) || !shortString(record.filePath) || !Number.isFinite(record.startedAt) ||
      record.repositoryId !== repositoryId || (record.editId !== undefined && !shortString(record.editId, 128)) ||
      (repositoryId && !shortString(record.sourcePath))) throw new Error('Invalid recovery record');
    return { status: 'found', record };
  } catch {
    return { status: 'unavailable', error: 'The browser recovery record could not be read. Inspect the current source before starting another editing session.' };
  }
}

export function saveStudioRecovery(record: Omit<StudioRecoveryRecord, 'version' | 'operationId' | 'startedAt'>, storage?: RecoveryStorage): StudioRecoveryRecord {
  const next: StudioRecoveryRecord = { ...record, version: 1, operationId: crypto.randomUUID(), startedAt: Date.now() };
  const serialized = JSON.stringify(next);
  if (serialized.length > maxBytes) throw new Error('This editing session is too large to preserve for recovery. No write was sent.');
  try { (storage || browserStorage()).setItem(keyFor(record.repositoryId), serialized); }
  catch { throw new Error('The browser could not preserve this operation for recovery. No write was sent. Enable session storage, then try again.'); }
  return next;
}

export function clearStudioRecovery(record: StudioRecoveryRecord, storage?: RecoveryStorage): boolean {
  try {
    const target = storage || browserStorage();
    const current = readStudioRecovery(record.repositoryId, target);
    if (current.status === 'empty') return true;
    // A late result must never remove another operation's recovery reference.
    if (current.status !== 'found' || current.record.operationId !== record.operationId) return false;
    target.removeItem(keyFor(record.repositoryId));
    return true;
  } catch { return false; }
}

import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import { lstat, readFile } from 'node:fs/promises';
import path from 'node:path';
import { promisify } from 'node:util';
import { resolveRepositoryRoot } from './repository-store';

const execFileAsync = promisify(execFile);
const image = 'node:22-bookworm-slim';

function dockerCandidates() {
  const candidates = [
    process.env.DOCKER_CLI,
    process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs', 'DockerDesktop', 'resources', 'bin', 'docker.exe'),
    'C:\\Program Files\\Docker\\Docker\\resources\\bin\\docker.exe',
    'docker',
  ].filter((item): item is string => Boolean(item));
  return [...new Set(candidates)];
}

async function docker(args: string[], timeout = 15_000) {
  let lastError: unknown;
  for (const binary of dockerCandidates()) {
    try {
      return await execFileAsync(binary, args, { timeout, windowsHide: true, maxBuffer: 256 * 1024 });
    } catch (error) {
      lastError = error;
      const code = (error as NodeJS.ErrnoException).code;
      if (code === 'ENOENT' || code === 'EACCES') continue;
      throw error;
    }
  }
  throw lastError || new Error('Docker Desktop CLI was not found.');
}

function getNames(repositoryId: string) {
  const suffix = createHash('sha256').update(repositoryId).digest('hex').slice(0, 12);
  return { container: `slightnudge-preview-${suffix}`, dependencies: `slightnudge-deps-${suffix}`, build: `slightnudge-build-${suffix}` };
}

function asDockerPath(value: string) {
  return path.resolve(value).replace(/\\/g, '/');
}

async function exists(filePath: string) {
  try { return (await lstat(filePath)).isFile(); } catch { return false; }
}

async function getRepoConfig(repositoryId: string) {
  const root = await resolveRepositoryRoot(repositoryId);
  const packagePath = path.join(root, 'package.json');
  const manifest = JSON.parse(await readFile(packagePath, 'utf8')) as {
    scripts?: Record<string, string>;
    dependencies?: Record<string, string>;
    devDependencies?: Record<string, string>;
    packageManager?: string;
  };
  if (!manifest.scripts?.dev) throw new Error('This repository does not define a “dev” script in package.json.');
  const dependencies = { ...manifest.dependencies, ...manifest.devDependencies };
  let manager = manifest.packageManager?.split('@')[0];
  if (!manager) {
    if (await exists(path.join(root, 'pnpm-lock.yaml'))) manager = 'pnpm';
    else if (await exists(path.join(root, 'yarn.lock'))) manager = 'yarn';
    else if (await exists(path.join(root, 'package-lock.json'))) manager = 'npm';
  }
  if (!['npm', 'pnpm', 'yarn'].includes(manager || '')) throw new Error('Add a package lockfile (npm, pnpm, or Yarn) before starting this preview.');
  const lockfile = manager === 'pnpm' ? 'pnpm-lock.yaml' : manager === 'yarn' ? 'yarn.lock' : 'package-lock.json';
  if (!(await exists(path.join(root, lockfile)))) throw new Error(`The package manager declares ${manager}, but ${lockfile} is missing. Add its lockfile before starting this preview.`);

  let install: string;
  if (manager === 'npm') install = await exists(path.join(root, 'package-lock.json')) ? 'npm ci' : 'npm install --package-lock=false';
  else if (manager === 'pnpm') install = 'corepack pnpm install --frozen-lockfile --store-dir=/tmp/pnpm-store';
  else {
    const yarnLock = await readFile(path.join(root, 'yarn.lock'), 'utf8').catch(() => '');
    install = yarnLock.includes('__metadata:') ? 'corepack yarn install --immutable' : 'corepack yarn install --frozen-lockfile';
  }

  const framework = dependencies.next ? 'next' : dependencies.vite ? 'vite' : 'generic';
  if (framework === 'generic') throw new Error('Automatic Docker previews currently support Next.js and Vite projects. Connect another framework with its own local preview command.');
  const start = framework === 'next'
    ? 'npm run dev -- --hostname 0.0.0.0 --port 3000'
    : framework === 'vite'
      ? 'npm run dev -- --host 0.0.0.0 --port 3000'
      : 'HOST=0.0.0.0 HOSTNAME=0.0.0.0 PORT=3000 npm run dev';
  const run = `${install} && ${start}`;
  return { root, run, names: getNames(repositoryId) };
}

async function getContainerState(name: string) {
  try {
    const { stdout } = await docker(['inspect', '--format', '{{.State.Status}}', name]);
    return stdout.trim() || 'unknown';
  } catch {
    return 'missing';
  }
}

async function previewLogs(name: string) {
  try {
    const { stdout, stderr } = await docker(['logs', '--tail', '30', name]);
    return `${stdout}${stderr}`.slice(-6000);
  } catch (error) {
    return error instanceof Error ? error.message.slice(0, 500) : 'Container logs are unavailable.';
  }
}

export async function getDockerPreviewStatus(repositoryId: string) {
  await resolveRepositoryRoot(repositoryId);
  const names = getNames(repositoryId);
  try {
    await docker(['info', '--format', '{{.ServerVersion}}']);
  } catch {
    return { available: false, state: 'docker-unavailable', url: null, logs: '', message: 'Start Docker Desktop and wait for “Engine running”.' };
  }
  const state = await getContainerState(names.container);
  const logs = state === 'running' || state === 'exited' ? await previewLogs(names.container) : '';
  return {
    available: true,
    state,
    url: state === 'running' ? 'http://127.0.0.1:3001' : null,
    logs,
    message: state === 'running' ? 'Preview container is running.' : state === 'exited' ? 'The dev server stopped. Review its logs before trying again.' : 'No preview container is running.',
  };
}

export async function startDockerPreview(repositoryId: string) {
  const { root, run, names } = await getRepoConfig(repositoryId);
  try {
    await docker(['info', '--format', '{{.ServerVersion}}']);
  } catch {
    throw new Error('Docker Desktop is not ready. Start it and wait for “Engine running”.');
  }
  const previousState = await getContainerState(names.container);
  if (previousState === 'running') return { started: true, url: 'http://127.0.0.1:3001', message: 'The preview container is already running.' };
  if (previousState !== 'missing') await docker(['rm', '--force', names.container]);

  const args = [
    'run', '--detach', '--name', names.container,
    '--label', 'slightnudge.managed=true',
    '--publish', '127.0.0.1:3001:3000',
    '--memory', '2g', '--memory-swap', '2g', '--cpus', '2', '--pids-limit', '256',
    '--cap-drop', 'ALL', '--security-opt', 'no-new-privileges', '--read-only',
    '--tmpfs', '/tmp:rw,noexec,nosuid,size=768m', '--tmpfs', '/root/.npm:rw,nosuid,size=512m', '--tmpfs', '/root/.cache:rw,nosuid,size=256m',
    '--mount', `type=bind,source=${asDockerPath(root)},target=/workspace,readonly`,
    '--mount', `type=volume,source=${names.dependencies},target=/workspace/node_modules`,
    '--mount', `type=volume,source=${names.build},target=/workspace/.next`,
    '--workdir', '/workspace', '--env', 'CI=1',
    '--env', 'HOST=0.0.0.0', '--env', 'HOSTNAME=0.0.0.0', '--env', 'PORT=3000', '--env', 'COREPACK_HOME=/tmp/corepack',
    '--restart', 'no', '--pull', 'missing', image,
    'sh', '-lc', run,
  ];
  try {
    await docker(args, 180_000);
    return { started: true, url: 'http://127.0.0.1:3001', message: 'The isolated preview is starting. Dependency installation may take a few minutes on first launch.' };
  } catch (error) {
    const details = (error as { stderr?: string; message?: string }).stderr || (error as Error).message || '';
    const lower = details.toLowerCase();
    if (lower.includes('port is already allocated') || lower.includes('address already in use')) {
      throw new Error('Port 3001 is already in use. Stop the existing preview and try again.');
    }
    if (lower.includes('no such image') || lower.includes('pull access denied') || lower.includes('failed to resolve source metadata')) {
      throw new Error('Docker could not download the Node.js runtime image. Check the network connection and try again.');
    }
    if (lower.includes('cannot connect') || lower.includes('pipe/docker_engine')) {
      throw new Error('Docker Desktop is not ready. Start it and wait for “Engine running”.');
    }
    throw new Error(`Could not start the isolated preview: ${details.slice(0, 600)}`);
  }
}

export async function stopDockerPreview(repositoryId: string) {
  await resolveRepositoryRoot(repositoryId);
  const names = getNames(repositoryId);
  const state = await getContainerState(names.container);
  if (state !== 'missing') await docker(['rm', '--force', '--volumes', names.container]);
  for (const volume of [names.dependencies, names.build]) {
    await docker(['volume', 'rm', volume]).catch(() => undefined);
  }
  return { stopped: true, message: 'The preview container and its temporary dependency/build volumes were removed.' };
}

